    D_8009D1A0 = 0u;
    PE_StoreU32(0x800B0CD8u, actor);
    PE_StoreU8(0x800B0CD8u + 0xF4u, 0x3Bu);
    PE_StoreU32(actor, 0xFFFFFFFFu);
    PE_StoreU32(binder, 0x00800002u);
    PE_StoreU8(0x800B0CD8u + 0x0Cu, 0u);
    PE_StoreU8(0x800B0CD8u + 0x0Du, 0u);
