    ASSERT(func_80018F54() == 1, "0x88 v0=1");
    ASSERT(PE_LoadU8(0x800BCFEEu) == 0xBFu, "&=~0x40");
    ASSERT(PE_LoadU32(0x8009D28Cu) == 0u, "mode stays 0");
