    ASSERT(PE_LoadU32(actor + 0x68u) == 0u, "Up vx");
    ASSERT(PE_LoadU32(actor + 0x70u) == 0x50000u, "Up vz 0x50000");

    PE_StoreU32(0x80122190u, 0x15u);
    PE_StoreU32(actor + 0x70u, 0u);
