    PE_StoreU16(rec + 0xCu, 10u);
    PE_StoreU16(rec + 0xEu, 20u);
    PE_StoreU16(rec + 0x1Cu, 0x80u);
    PE_StoreU16(rec + 0x1Eu, 0x100u);
    PE_StoreU8(rec + 0x20u, 0x80u);
    PE_StoreU8(rec + 0x22u, 0u);
