    PE_StoreU16(rec + 0x1Cu, 40u);
    PE_StoreU16(rec + 0x0Eu, 40u);
    PE_StoreU16(rec + 0x10u, 0u);
    PE_StoreU16(rec + 0x20u, 0u);
    PE_StoreU16(rec + 0x24u, 0u);
