    pe_addr_t ebody = 0x80108800u;
    pe_addr_t weapon = 0x80108900u;

    TEST("BTL111_reaction_waits_for_clip");
    ResetTestState();
    BTL_SeedDamageTextPackets();
    BTL109_SeedHitClips();
    PE_StoreU32(0x8009D254u, aya);
    PE_StoreU32(0x8009D278u, rec);
