    PE_StoreU32(0x800A5D54u, 0xA5A5A5A5u);
    PE_StoreU32(0x800B0CCCu, 0xA5A5A5A5u);

    func_8007C304(2u, -7, -9, 0xF1234567u, 0x89ABCDEFu);
