/* ── Phase 6E-B45: func_80087090 SPU upload retry wrapper ────────────── */
/* ── Phase 6E-B46: func_800851A8 prefix translation ─────────────────── */

/* B46 magic number: func_80085084 checks *buffer + 0xB0BEB4BF == 0,
 * so the buffer must start with 0x4F414B41 for the check to pass. */
#define B46_MAGIC  0x4F414B41u

/* B46 helper: seed the magic number at the start of a buffer. */
static void B46_SeedMagic(pe_addr_t buf) {
    /* The retail upload is reached only after SsInit installed DMA4's IRQ
     * handler.  Direct wrapper tests establish that prerequisite without
     * fabricating a completion event. */
    PE_SpuDma_InstallIrq(PE_SPU_DMA_IRQ_HANDLER);
    PE_StoreU32(0x8009B418u, 0); /* func_80085F14(0): DMA mode */
    PE_StoreU32(0x8009B424u, 3); /* eight-byte SPU address units */
    PE_StoreU16(0x8009B414u, 0); /* safe destination for zero/default data */
    PE_StoreU32(buf, B46_MAGIC);
}

/* B45 helper: set func_800851A8 to return specific values via bootstrap
 * sequence.  Only used when the magic number check passes and the
 * success path routes through the bootstrap boundary. */
static void B45_Set851A8Sequence(const int *vals, int count) {
    Bootstrap_SetIntSequence("func_800851A8", vals, count);
}

/* Test 1: func_800851A8 magic number check + error path.
 * B48: func_800851A8 is fully translated (extended prefix + DMA transfer).
 * Returns -1 on failure, 0 on success.  No bootstrap boundary on success
 * path (func_800850F4 is translated). */
static void test_87090_signature_and_retry(void)
{
    TEST("87090_signature_and_retry");
    int (*fn)(pe_addr_t, int) = func_80087090;
    int ret;

    /* Invalid buffer (no magic number) → func_800851A8 returns -1 */
    ResetTestState();
    PE_StoreU32(0x80100000u, 0xA5A5A5A5u);  /* canary, not magic */
    ret = fn(0x80100000u, 1);
    ASSERT(ret == -1, "invalid buffer must return -1");
    ASSERT(g_stub_order_count == 0, "no bootstrap call on error path");
    ASSERT(PE_LoadU32(0x8009D24Cu) != 0,
           "D_8009D24C must be set on error path");

    /* Valid buffer (magic number) → deterministic path, returns 0.
     * B48: func_800851A8 is fully translated.  No bootstrap boundary. */
    ResetTestState();
    B46_SeedMagic(0x80100000u);
    ret = fn(0x80100000u, 1);
    ASSERT(ret == 0, "valid buffer must return 0");
    ASSERT(g_stub_order_count == 0, "no bootstrap call (fully translated)");

    /* func_800851A8 is deterministic — retry via bootstrap sequence
     * no longer applies.  func_80087090's retry loop (ret == 1) is
     * dead code in retail: func_800851A8 returns 0 on success, -1 on
     * error, never 1. */
    ResetTestState();
    B46_SeedMagic(0x80100000u);
    ret = fn(0x80100000u, 1);
    ASSERT(ret == 0, "deterministic success returns 0");
    ASSERT(g_stub_order_count == 0, "no bootstrap call (fully translated)");

    Bootstrap_ClearSequences();
    PASS();
}

/* Test 2: func_80087090, func_800851A8, and func_800850F4 are translated. */
static void test_87090_not_bootstrap_stub(void)
{
    TEST("87090_not_bootstrap_stub");
    ResetTestState();
    B46_SeedMagic(0x80100000u);
    func_80087090(0x80100000u, 0);
    /* None of func_80087090, func_800851A8, func_800850F4 should appear
     * in the bootstrap log — they are all translated. */
    ASSERT(CountOrderLog("func_80087090") == 0,
           "translated func_80087090 must not be a bootstrap provider");
    ASSERT(CountOrderLog("func_800851A8") == 0,
           "translated func_800851A8 must not be a bootstrap provider");
    ASSERT(CountOrderLog("func_800850F4") == 0,
           "translated func_800850F4 must not be a bootstrap provider");
    PASS();
}

