/* Test 5: full 2 MiB canary — func_80087090 + func_800851A8 prefix
 * writes only to stack and D_8009D24C (completion flag).
 * B46: seed magic number so the success path is taken (error path
 * would store to D_8009D24C). */
static void test_87090_full_ram_canary(void)
{
    TEST("87090_full_ram_canary");
    uint32_t i;
    ResetTestState();
    PE_RamReset();
    /* Poison all 2 MiB */
    for (i = 0; i < 0x200000u; i += 4)
        PE_StoreU32(0x80000000u + i, 0xA5A5A5A5u);
    /* Seed magic and the already-installed retail DMA prerequisite after
     * poisoning guest RAM. */
    B46_SeedMagic(0x80100000u);
    func_80087090(0x80100000u, 1);
    /* Verify no guest memory was modified except:
     * - D_8009D24C (completion flag)
     * - D_8009B434 (callback pointer, set/cleared by func_800850F4)
     * - D_8009B430 (callback state, cleared by func_800850F4)
     * - buffer start (magic number seeded) */
    for (i = 0; i < 0x200000u; i += 4) {
        uint32_t addr = 0x80000000u + i;
        uint32_t v = PE_LoadU32(addr);
        /* D_8009D24C is allowed to change (completion flag) */
        if (addr == 0x8009D24Cu) continue;
        /* D_8009B434 and D_8009B430 are set/cleared by func_800850F4 */
        if (addr == 0x8009B434u) continue;
        if (addr == 0x8009B430u) continue;
        if (addr == 0x8009B414u) continue;
        if (addr == 0x8009B418u) continue;
        if (addr == 0x8009B424u) continue;
        if (addr == 0x8009B44Cu) continue;
        if (addr == 0x8009B450u) continue;
        if (addr == 0x8009B454u) continue;
        /* Buffer start has magic number seeded */
        if (addr == 0x80100000u) continue;
        if (v != 0xA5A5A5A5u) {
            printf("  FAIL: canary corrupted at 0x%08X: 0x%08X\n",
                   addr, v);
            FAIL("87090 canary corrupted");
            return;
        }
    }
    PASS();
}

