    ASSERT(func_8005332C(0) == 0x800C0ECCu,
           "first dirty-state lookup wrong");
    ASSERT(func_8005332C(0) == 0x800C0ECCu,
           "repeated lookup changed result");
    ASSERT(PE_LoadU32(B40_TABLE + 4u) == 0xDEADBEEFu,
           "read-only lookup changed dirty neighbor");

