static void test_6AD40_strict_completes_without_frontier(void)
{
    DiscFixture fx;
    /* The complete direct function contains no bootstrap provider. B54K-S
     * gives its retail DrawSync(0) the hardware-completion opportunity that
     * now drains the seeded GPU DMA before normal return. */
    TEST_RETAIL_DISC1("6AD40_strict_completes_without_frontier"); TEST_RETAIL_FIXUPS(RETAILFIX_dispenv);
    pid_t pid;
    int status = 0;
    ResetTestState();
    ASSERT(FxBuild(&fx, 0), "fixture build failed");
    pid = fork();
    ASSERT(pid >= 0, "fork failed for B51 strict boundary");
    if (pid == 0) {
        PE_Disc_SetActive(fx.disc);
        HostFB_Init();
        Bootstrap_Init();
        Bootstrap_EnableStrict();
        func_8007ED58();  /* CD reset — sets drive state after bootstrap init */
        HostFB_VSync(0);  /* advance VSync counter for DMA poll */
        B50_SeedPrefixState(1);
        PE_StoreU8(B53D_INIT_BYTE, 1u);
        if (!B53E_SeedBusyDma()) _exit(2);
        _exit(func_8006AD40() == 0 ? 0 : 3);
    }
    ASSERT(waitpid(pid, &status, 0) == pid,
           "waitpid failed for B51 strict boundary");
    ASSERT(WIFEXITED(status) && WEXITSTATUS(status) == 0,
           "strict complete function did not return normally");

    /* Same path in normal mode: prove exact completion with no provider. */
    ResetTestState();
    PE_Disc_SetActive(fx.disc);
    HostFB_Init();
    Bootstrap_Init();
    func_8007ED58();
    HostFB_VSync(0);
    B50_SeedPrefixState(1);
    PE_StoreU8(B53D_INIT_BYTE, 1u);
    ASSERT(B53E_SeedBusyDma(), "busy DMA seed failed");
    Stub_ResetOrderLog();
    func_8006AD40();
    ASSERT(B54KM_CompletionStateIsExact(),
           "normal complete path retained a boundary or wrong final state");
    /* The seeded DMA (issued before 6AD40, DICR = 0) now completes at the
     * first CD read issue (func_8006E6D4 services pending GPU DMA before the
     * host delivers the sectors — on hardware the 16-word block finishes in
     * microseconds, long before a sector arrives).  DICR is still 0 there,
     * so no DMA2 IRQ flag is raised; psx-spx "DMA": DICR flags 24-30 are set
     * on completion only while the channel's enable bit (16-22) is set, and
     * enabling it later does not set the flag retroactively.  The old
     * expectation (flag raised at DrawSync) encoded the host's late
     * completion, after the fixture's DICR enable. */
    ASSERT(!PE_GPU_DMA2Pending() && !PE_GPU_DMA2CompletionPending(),
           "seeded DMA was not completed at hardware time (before DICR enable)");
    FxFree(&fx);
    PASS();
}

