static void test_B53E_dispatcher_and_inline_integration(void)
{
    RECT inline_rect = { 4, 5, 1, 1 };
    uint8_t ring_before[32];
    TEST("B53E_dispatcher_and_inline_integration");
    ResetTestState();
    B53E_SetupRetailGpu();
    PE_StoreU8(B53D_INIT_BYTE, 1u);
    B53E_StoreRect(2, 3, 1, 1);
    PE_StoreU32(B53E_SOURCE, 0x22221111u);
    PE_Fill(B53C_RING_BASE, sizeof(ring_before), 0xA5u);
    memcpy(ring_before, PE_TranslateConst(B53C_RING_BASE,
                                         sizeof(ring_before)),
           sizeof(ring_before));
    (void)PE_IRQ_ExchangeMask(0xBEEFu);
    ASSERT(func_80076C34(0x80076664u, B53E_RECT, 8,
                         B53E_SOURCE) == 0,
           "guest dispatcher direct path did not return retail zero");
    ASSERT(B53B_Pixel(2, 3) == 0x1111u &&
           PE_IRQ_GetMask() == 0xBEEFu &&
           PE_LoadU32(B53D_SAVED_IMASK) == 0xBEEFu,
           "direct worker issue or I_MASK restore is wrong");
    ASSERT(memcmp(ring_before, PE_TranslateConst(B53C_RING_BASE,
                                                 sizeof(ring_before)),
                  sizeof(ring_before)) == 0 && g_stub_count == 0,
           "direct issue touched the ring or a callback/pump");

    ResetTestState();
    B53E_SetupRetailGpu();
    B52_SeedGpuDispatch();
    PE_StoreU32(B53E_SOURCE, 0x44443333u);
    ASSERT(func_8007506C(&inline_rect, B53E_SOURCE) == 0 &&
           g_bootstrap_arg4_call_count == 1,
           "inline wrapper did not use one by-value dispatcher snapshot");
    B52_AssertGpuCall(0, 0x00050004u, B53E_SOURCE, 0x00010001u);
    ASSERT(B53B_Pixel(4, 5) == 0x3333u &&
           CountOrderLog("func_80076664") == 0,
           "inline worker remained a boundary or retained a pointer");

    /* Dispatcher retail code is not a host-safe run-control poll.  A frame
     * budget that has become eligible must not masquerade as a nested worker
     * boundary and suppress the mandatory I_MASK restore. */
    ResetTestState();
    B53E_SetupRetailGpu();
    PE_StoreU8(B53D_INIT_BYTE, 1u);
    B53E_StoreRect(6, 7, 1, 1);
    PE_StoreU32(B53E_SOURCE, 0x66665555u);
    (void)PE_IRQ_ExchangeMask(0xBEEFu);
    PE_Port_SetFrameLimit(1);
    PE_Port_FramePresented(1);
    ASSERT(func_80076C34(0x80076664u, B53E_RECT, 8,
                         B53E_SOURCE) == 0 &&
           PE_IRQ_GetMask() == 0xBEEFu &&
           PE_Port_GetStopReason() == PE_PORT_STOP_NONE,
           "host frame policy suppressed the retail I_MASK restore");
    ASSERT(PE_Port_ShouldStop() &&
           PE_Port_GetStopReason() == PE_PORT_STOP_FRAME_LIMIT,
           "host-safe continuation did not consume the pending frame limit");
    PASS();
}

/* ═══════════════════════════════════════════════════════════════════
 * Phase 6E-B53F — func_80073CF4 installed-target wrapper (4 tests)
 *
 * The 12-word retail wrapper has no callback or hardware state of its own.
 * It forwards channel/handler to the ResetCallback-installed func_800746A0
 * guest identity and forwards that backend's v0.  B53G translates that
 * backend completely, so the wrapper is now a complete retail function and
 * every effect below is the setter's own exact registration effect.
 * ════════════════════════════════════════════════════════════════════ */

static void test_B53F_exact_abi_and_return_forwarding(void)
{
    static const uint32_t channels[] = { 2u, 3u, 4u };
    static const pe_addr_t handlers[] = {
        B53D_QUEUE_PUMP, 0xFFFFFFFFu, 0x81234567u
    };
    static const pe_addr_t seeded[] = {
        0x12345678u, 0x89ABCDEFu, 0xFFFFFFFEu
    };
    TEST("B53F_exact_abi_and_return_forwarding");
    ResetTestState();
    for (size_t i = 0; i < 3u; i++) {
        PE_StoreU32(B53F_DMA_CB_TABLE + channels[i] * 4u, seeded[i]);
    }

    /* The wrapper forwards both arguments and the backend's full 32-bit
     * v0 without truncation, normalisation, or a native pointer. */
    for (size_t i = 0; i < 3u; i++) {
        ASSERT(func_80073CF4(channels[i], handlers[i]) == seeded[i],
               "wrapper did not forward the backend's full 32-bit v0");
        ASSERT(PE_LoadU32(B53F_DMA_CB_TABLE + channels[i] * 4u)
               == handlers[i],
               "wrapper did not reach the exact guest callback slot");
    }
    ASSERT(g_bootstrap_arg4_call_count == 0 &&
           CountOrderLog("func_80073CF4") == 0 &&
           CountOrderLog("func_800746A0") == 0,
           "translated wrapper or setter remained a bootstrap boundary");
    ASSERT(PE_Port_GetStopReason() == PE_PORT_STOP_NONE,
           "complete wrapper still requested an unresolved-boundary stop");
    PASS();
}

static void test_B53F_touches_only_slot_and_dicr(void)
{
    uint8_t *ram_before;
    uint32_t published = B53D_QUEUE_PUMP;
    PeGpuState gpu_before;
    PeGpuState gpu_after;
    TEST("B53F_touches_only_slot_and_dicr");
    ResetTestState();
    PE_Fill(PE_RAM_BASE, PE_RAM_SIZE, 0xA5u);
    for (uint32_t i = 0; i < 8u; i++) {
        PE_StoreU32(B53F_DMA_CB_TABLE + i * 4u,
                    0x80010000u + i * 0x100u);
    }
    PE_StoreU32(B53C_PRODUCER, 63u);
    PE_StoreU32(B53C_CONSUMER, 17u);
    (void)PE_IRQ_ExchangeMask(0xBEEFu);
    PE_GPU_WriteDPCR(0xA5A50855u);
    PE_GPU_WriteDICR(0x00A5A5A5u);
    PE_GPU_SetReady(0);
    ram_before = malloc(PE_RAM_SIZE);
    ASSERT(ram_before != NULL, "cannot allocate B53F RAM snapshot");
    memcpy(ram_before, PE_TranslateConst(PE_RAM_BASE, PE_RAM_SIZE),
           PE_RAM_SIZE);
    PE_GPU_GetState(&gpu_before);

    ASSERT(func_80073CF4(2u, B53D_QUEUE_PUMP) == 0x80010200u,
           "wrapper did not return the seeded slot-2 identity");

    /* Exactly one guest word changes: callback slot 2. */
    memcpy(ram_before + (B53F_DMA_CB_SLOT2 - PE_RAM_BASE), &published, 4u);
    ASSERT(memcmp(ram_before,
                  PE_TranslateConst(PE_RAM_BASE, PE_RAM_SIZE),
                  PE_RAM_SIZE) == 0,
           "wrapper mutated guest state outside callback slot 2");

    /* Exactly one hardware field changes: DICR. */
    PE_GPU_GetState(&gpu_after);
    ASSERT(PE_GPU_ReadStoredDICR() ==
               ((0x00A5A5A5u & 0x00FFFFFFu) |
                0x00040000u | 0x00800000u) &&
           gpu_after.dicr ==
               (((0x00A5A5A5u & 0x00FFFFFFu) |
                 0x00040000u | 0x00800000u) | 0x80000000u),
           "wrapper DICR result is not the retail install RMW");
    gpu_before.dicr = gpu_after.dicr;
    ASSERT(memcmp(&gpu_before, &gpu_after, sizeof(gpu_before)) == 0 &&
           PE_IRQ_GetMask() == 0xBEEFu,
           "wrapper mutated GPU/DMA/DPCR/I_MASK state beyond DICR");
    free(ram_before);
    PASS();
}

static void test_B53F_strict_wrapper_completes(void)
{
    pid_t pid;
    int status = 0;
    TEST("B53F_strict_wrapper_completes");
    ResetTestState();
    pid = fork();
    ASSERT(pid >= 0, "fork failed for B53F strict completion");
    if (pid == 0) {
        Bootstrap_Init();
        Bootstrap_EnableStrict();
        /* B53G removed this boundary: a complete wrapper must not abort
         * under strict stubs, and must return the retail previous value. */
        if (func_80073CF4(2u, B53D_QUEUE_PUMP) != 0u) _exit(3);
        if (PE_LoadU32(B53F_DMA_CB_SLOT2) != B53D_QUEUE_PUMP) _exit(4);
        _exit(0);
    }
    ASSERT(waitpid(pid, &status, 0) == pid,
           "waitpid failed for B53F strict completion");
    ASSERT(WIFEXITED(status) && WEXITSTATUS(status) == 0,
           "strict wrapper no longer completes without a boundary");
    PASS();
}

static void test_B53F_pending_dma_dispatcher_integration(void)
{
    PeGpuState before;
    PeGpuState after;
    TEST("B53F_pending_dma_dispatcher_integration");
    ResetTestState();
    PE_StoreU8(B53D_INIT_BYTE, 1u);
    PE_StoreU32(B53F_DMA_CB_SLOT2, 0x80016666u);
    PE_StoreU32(B53E_RECT, 0x11112222u);
    PE_StoreU32(B53E_RECT + 4u, 0x33334444u);
    (void)PE_IRQ_ExchangeMask(0xBEEFu);
    ASSERT(B53E_SeedBusyDma(), "cannot seed canonical pending DMA2 state");
    PE_GPU_GetState(&before);

    ASSERT(func_80076C34(0x80076664u, B53E_RECT, 8,
                         0x80110000u) == 1,
           "dispatcher did not return the retail pending count");
    PE_GPU_GetState(&after);

    /* The registration really happened, through the real setter. */
    ASSERT(g_bootstrap_arg4_call_count == 0 &&
           CountOrderLog("func_800746A0") == 0 &&
           PE_LoadU32(B53F_DMA_CB_SLOT2) == B53D_QUEUE_PUMP,
           "dispatcher did not perform the real callback registration");
    ASSERT(after.dicr == 0x00840000u,
           "dispatcher registration DICR result is not 0x00840000");

    /* Publication is retail-exact and the pending DMA is untouched. */
    ASSERT(PE_LoadU32(B53C_RING_BASE) == 0x80076664u &&
           PE_LoadU32(B53C_RING_BASE + 4u) == B53C_RING_BASE + 0x0Cu &&
           PE_LoadU32(B53C_RING_BASE + 8u) == 0x80110000u &&
           PE_LoadU32(B53C_RING_BASE + 0x0Cu) == 0x11112222u &&
           PE_LoadU32(B53C_RING_BASE + 0x10u) == 0x33334444u,
           "published ring entry differs from retail");
    ASSERT(PE_LoadU32(B53C_PRODUCER) == 1u &&
           PE_LoadU32(B53C_CONSUMER) == 0u,
           "publication moved the consumer or mispublished the producer");
    before.dicr = after.dicr;
    ASSERT(memcmp(&before, &after, sizeof(before)) == 0 &&
           PE_GPU_DMA2Pending() && !PE_GPU_DMA2CompletionPending(),
           "dispatcher progressed or completed the pending DMA");
    /* B53H: the busy-DMA pump really returned 1 and consumed nothing, so
     * the dispatcher completes with no boundary at all. */
    ASSERT(PE_LoadU32(B53D_SAVED_IMASK) == 0xBEEFu &&
           PE_IRQ_GetMask() == 0xBEEFu &&
           CountOrderLog("func_80076EE4_idle_pump") == 0 &&
           PE_Port_GetStopReason() == PE_PORT_STOP_NONE,
           "dispatcher did not restore I_MASK or fabricated a boundary");
    PASS();
}

/* ═══════════════════════════════════════════════════════════════════
 * Phase 6E-B53G — func_800746A0 DMA callback-slot setter (7 tests)
 *
 * Every expectation below is derived from the 43 literal retail words and
 * cross-checked by the independent tools/b53g_oracle.py.  The setter is
 * registration state only: it never delivers an interrupt, services DMA,
 * pumps the ring, or invokes a callback.
 * ════════════════════════════════════════════════════════════════════ */

#define B53G_DICR_MASTER   0x00800000u
#define B53G_DICR_CONTROL  0x00FFFFFFu

static uint32_t B53G_EnableBit(uint32_t channel)
{
    return 1u << ((channel + 16u) & 31u);
}

static void test_B53G_exact_abi_and_caller_contract(void)
{
    /* The three channels every executable caller of func_80073CF4 uses. */
    static const uint32_t channels[] = { 2u, 3u, 4u };
    static const pe_addr_t handlers[] = {
        0x80076EE4u, 0x80077A00u, 0xFFFFFFFFu
    };
    TEST("B53G_exact_abi_and_caller_contract");
    ResetTestState();

    for (size_t i = 0; i < 3u; i++) {
        ASSERT(PE_DMA_CallbackSlotAddress(channels[i])
               == B53F_DMA_CB_TABLE + channels[i] * 4u,
               "channel-to-slot mapping is not base + channel*4");
        ASSERT(func_800746A0(channels[i], handlers[i]) == 0u,
               "first install did not return the retail zero slot");
        ASSERT(PE_LoadU32(B53F_DMA_CB_TABLE + channels[i] * 4u)
               == handlers[i],
               "install stored a truncated or normalised identity");
    }
    /* Full 32-bit guest identities survive; nothing is a native pointer. */
    ASSERT(func_800746A0(4u, 0x81234567u) == 0xFFFFFFFFu,
           "previous-handler return lost its high guest bits");
    ASSERT(PE_LoadU32(B53F_DMA_CB_TABLE + 16u) == 0x81234567u,
           "replacement did not store the full 32-bit identity");
    /* The retail authorities are named, not duplicated. */
    ASSERT(PE_DMA_DicrPointerAddress() == 0x800956BCu &&
           PE_DMA_DicrMmioAddress() == 0x1F8010F4u,
           "DICR authority addresses differ from retail");
    ASSERT(g_bootstrap_arg4_call_count == 0 &&
           CountOrderLog("func_800746A0") == 0,
           "translated setter still routed through a bootstrap boundary");
    PASS();
}

static void test_B53G_channel_range_contract(void)
{
    TEST("B53G_channel_range_contract");
    ResetTestState();

    /* Retail performs no minimum, maximum, or signedness check: every one
     * of the eight table slots is reachable and indexed identically. */
    for (uint32_t channel = 0u; channel < 8u; channel++) {
        ASSERT(func_800746A0(channel, 0x80020000u + channel) == 0u,
               "in-range channel did not start from the cleared slot");
    }
    for (uint32_t channel = 0u; channel < 8u; channel++) {
        ASSERT(PE_LoadU32(B53F_DMA_CB_TABLE + channel * 4u)
               == 0x80020000u + channel,
               "in-range channel indexed the wrong slot");
    }

    /* Above range: channel 8 addresses the word after the table, which the
     * retail image initialises to the DMA0 register-block pointer. */
    ResetTestState();
    ASSERT(func_800746A0(8u, 0x80009999u) == 0u,
           "above-range channel did not read one word past the table");
    ASSERT(PE_LoadU32(B53F_DMA_CB_TABLE + 32u) == 0x80009999u,
           "above-range channel did not write one word past the table");

    /* Below range: channel -1 wraps onto the DICR pointer word and its
     * shift amount lands on bit 15.  Both are exact retail consequences. */
    ResetTestState();
    PE_StoreU32(PE_DMA_DicrPointerAddress(), 0x1F8010F4u);
    ASSERT(func_800746A0(0xFFFFFFFFu, 0x80005555u) == 0x1F8010F4u,
           "negative channel did not read the DICR pointer word");
    ASSERT(PE_LoadU32(PE_DMA_DicrPointerAddress()) == 0x80005555u &&
           PE_GPU_ReadStoredDICR() ==
               (B53G_DICR_MASTER | 0x00008000u) &&
           PE_GPU_ReadDICR() ==
               (0x80000000u | B53G_DICR_MASTER | 0x00008000u),
           "negative channel was sanitised beyond retail");
    PASS();
}

static void test_B53G_handler_lifecycle(void)
{
    uint32_t dicr_seed;
    TEST("B53G_handler_lifecycle");

    /* empty -> install */
    ResetTestState();
    ASSERT(func_800746A0(2u, 0x80076EE4u) == 0u &&
           PE_LoadU32(B53F_DMA_CB_SLOT2) == 0x80076EE4u &&
           PE_GPU_ReadDICR() == 0x00840000u,
           "install into an empty slot differs from retail");

    /* existing -> replace, previous returned */
    ASSERT(func_800746A0(2u, 0x80077A00u) == 0x80076EE4u &&
           PE_LoadU32(B53F_DMA_CB_SLOT2) == 0x80077A00u,
           "replacement did not return and store the retail identities");

    /* existing -> remove with zero; master stays set, channel clears */
    ASSERT(func_800746A0(2u, 0u) == 0x80077A00u &&
           PE_LoadU32(B53F_DMA_CB_SLOT2) == 0u &&
           PE_GPU_ReadDICR() == B53G_DICR_MASTER,
           "removal differs from retail");

    /* zero -> zero is a complete no-op: no slot store, no DICR access */
    ResetTestState();
    PE_GPU_WriteDICR(0x00123456u);
    dicr_seed = PE_GPU_ReadDICR();
    ASSERT(func_800746A0(2u, 0u) == 0u &&
           PE_LoadU32(B53F_DMA_CB_SLOT2) == 0u &&
           PE_GPU_ReadDICR() == dicr_seed,
           "zero-to-zero touched the slot or DICR");

    /* same-handler reinstall is equally inert */
    ResetTestState();
    PE_StoreU32(B53F_DMA_CB_SLOT2, 0x80076EE4u);
    PE_GPU_WriteDICR(0x00123456u);
    dicr_seed = PE_GPU_ReadDICR();
    ASSERT(func_800746A0(2u, 0x80076EE4u) == 0x80076EE4u &&
           PE_LoadU32(B53F_DMA_CB_SLOT2) == 0x80076EE4u &&
           PE_GPU_ReadDICR() == dicr_seed,
           "same-handler reinstall performed a redundant DICR write");
    PASS();
}

static void test_B53G_dicr_rmw_exact(void)
{
    TEST("B53G_dicr_rmw_exact");

    /* Install: unrelated lower control bits are preserved exactly. */
    ResetTestState();
    PE_GPU_WriteDICR(0x005A1234u);
    ASSERT(func_800746A0(2u, 0x80076EE4u) == 0u &&
           PE_GPU_ReadDICR() ==
               ((0x005A1234u & B53G_DICR_CONTROL) |
                B53G_EnableBit(2u) | B53G_DICR_MASTER),
           "install RMW did not preserve unrelated control bits");

    /* Removal sets master first and clears the channel bit afterwards. */
    PE_StoreU32(B53F_DMA_CB_SLOT2, 0x80076EE4u);
    ASSERT(func_800746A0(2u, 0u) == 0x80076EE4u &&
           PE_GPU_ReadDICR() ==
               (((0x005A1234u & B53G_DICR_CONTROL) | B53G_DICR_MASTER) &
                ~B53G_EnableBit(2u)),
           "removal RMW did not preserve unrelated control bits");

    /* Channel 7's enable bit IS the master bit, so removal clears it. */
    ResetTestState();
    PE_StoreU32(B53F_DMA_CB_TABLE + 28u, 0x80001234u);
    PE_GPU_WriteDICR(B53G_DICR_MASTER);
    ASSERT(func_800746A0(7u, 0u) == 0x80001234u &&
           PE_GPU_ReadDICR() == 0u,
           "channel 7 removal did not clear the master bit it shares");
    ASSERT(B53G_EnableBit(7u) == B53G_DICR_MASTER,
           "channel 7 enable bit is not bit 23");

    /* A real pending completion flag is never acknowledged: the written
     * word carries zeros in bits 24..30, so W1C leaves the flag set. */
    ResetTestState();
    ASSERT(B53E_SeedBusyDma(), "cannot seed DMA for the flag test");
    PE_GPU_SetDMA2InterruptEnabled(1);
    ASSERT(PE_GPU_ServiceDMA2Completion(PE_GPU_DMA2EventToken()) == 1 &&
           PE_GPU_DMA2CompletionPending(),
           "completion flag seeding failed");
    ASSERT(func_800746A0(2u, 0x80076EE4u) == 0u &&
           PE_GPU_DMA2CompletionPending() &&
           PE_GPU_ReadDICR() ==
               (0x84000000u | B53G_EnableBit(2u) | B53G_DICR_MASTER),
           "install acknowledged a pending DMA completion flag");
    PE_StoreU32(B53F_DMA_CB_SLOT2, 0x80076EE4u);
    ASSERT(func_800746A0(2u, 0u) == 0x80076EE4u &&
           PE_GPU_DMA2CompletionPending() &&
           PE_GPU_ReadDICR() == (0x84000000u | B53G_DICR_MASTER),
           "removal acknowledged a pending DMA completion flag");

    /* Bit 31 is physical/derived on reads, never stored.  The setter masks
     * it away and does not acknowledge the retained completion flag. */
    ASSERT((PE_GPU_ReadDICR() & 0x80000000u) != 0u &&
           (PE_GPU_ReadStoredDICR() & 0x80000000u) == 0u,
           "physical/stored DICR bit-31 separation failed");
    PASS();
}

static void test_B53G_registration_is_not_delivery(void)
{
    uint8_t *ram_before;
    uint32_t slot = 0x80076EE4u;
    uint16_t pixel_before[4];
    uint16_t pixel_after[4];
    PeGpuState before;
    PeGpuState after;
    TEST("B53G_registration_is_not_delivery");
    ResetTestState();
    PE_Fill(PE_RAM_BASE, PE_RAM_SIZE, 0x5Au);
    PE_StoreU32(B53F_DMA_CB_SLOT2, 0u);
    (void)PE_IRQ_ExchangeMask(0xBEEFu);
    ASSERT(B53E_SeedBusyDma(), "cannot seed the canonical pending DMA");
    for (uint32_t i = 0; i < 4u; i++) {
        ASSERT(PE_GPU_ReadVRAM(i, 0u, &pixel_before[i]) == 1,
               "VRAM sample failed");
    }
    ram_before = malloc(PE_RAM_SIZE);
    ASSERT(ram_before != NULL, "cannot allocate B53G RAM snapshot");
    memcpy(ram_before, PE_TranslateConst(PE_RAM_BASE, PE_RAM_SIZE),
           PE_RAM_SIZE);
    PE_GPU_GetState(&before);

    ASSERT(func_800746A0(2u, 0x80076EE4u) == 0u,
           "canonical registration return changed");

    /* Exactly one guest word and exactly one hardware field changed. */
    memcpy(ram_before + (B53F_DMA_CB_SLOT2 - PE_RAM_BASE), &slot, 4u);
    ASSERT(memcmp(ram_before,
                  PE_TranslateConst(PE_RAM_BASE, PE_RAM_SIZE),
                  PE_RAM_SIZE) == 0,
           "registration mutated guest state outside its callback slot");
    PE_GPU_GetState(&after);
    ASSERT(after.dicr == (((before.dicr & B53G_DICR_CONTROL) |
                           B53G_EnableBit(2u)) | B53G_DICR_MASTER),
           "registration DICR result is not the retail install RMW");
    before.dicr = after.dicr;
    ASSERT(memcmp(&before, &after, sizeof(before)) == 0,
           "registration changed GPU readiness, DMA, VBlank, or parser");

    /* Registration is not delivery. */
    ASSERT(PE_GPU_DMA2Pending() == 1 &&
           PE_GPU_DMA2CompletionPending() == 0 &&
           PE_GPU_DMA2InterruptAsserted() == 0,
           "registration completed or asserted the pending DMA");
    ASSERT(PE_IRQ_GetMask() == 0xBEEFu,
           "registration touched the single I_MASK authority");
    ASSERT(g_stub_count == 0 && g_bootstrap_arg4_call_count == 0,
           "registration invoked a callback, pump, or boundary");
    for (uint32_t i = 0; i < 4u; i++) {
        ASSERT(PE_GPU_ReadVRAM(i, 0u, &pixel_after[i]) == 1 &&
               pixel_after[i] == pixel_before[i],
               "registration mutated VRAM");
    }
    free(ram_before);
    PASS();
}

static void test_B53G_reset_lifecycle_and_determinism(void)
{
    TEST("B53G_reset_lifecycle_and_determinism");

    /* Repeating the exact canonical registration is idempotent: the second
     * call takes the equality path and performs no write at all. */
    ResetTestState();
    ASSERT(func_800746A0(2u, 0x80076EE4u) == 0u &&
           PE_GPU_ReadDICR() == 0x00840000u, "first registration changed");
    PE_GPU_WriteDICR(0x00000000u);
    ASSERT(func_800746A0(2u, 0x80076EE4u) == 0x80076EE4u &&
           PE_GPU_ReadDICR() == 0u,
           "repeated identical registration was not inert");

    /* The table is guest-backed, so a guest RAM reset clears it exactly as
     * func_800744D4's func_8007474C(&D_800956C0, 8) does. */
    PE_RamReset();
    for (uint32_t channel = 0u; channel < 8u; channel++) {
        ASSERT(PE_LoadU32(B53F_DMA_CB_TABLE + channel * 4u) == 0u,
               "callback table survived a guest RAM reset");
    }
    ASSERT(func_800746A0(2u, 0x80076EE4u) == 0u,
           "post-reset registration did not start from a cleared slot");

    /* Three identical reset-and-register cycles agree exactly. */
    for (int i = 0; i < 3; i++) {
        ResetTestState();
        ASSERT(func_800746A0(2u, 0x80076EE4u) == 0u &&
               PE_LoadU32(B53F_DMA_CB_SLOT2) == 0x80076EE4u &&
               PE_GPU_ReadDICR() == 0x00840000u,
               "reset-and-register cycles are not deterministic");
    }
    PASS();
}

static void test_B53G_strict_registration_and_publication(void)
{
    pid_t pid;
    int status = 0;
    TEST("B53G_strict_registration_and_publication");
    ResetTestState();
    pid = fork();
    ASSERT(pid >= 0, "fork failed for B53G strict frontier");
    if (pid == 0) {
        Bootstrap_Init();
        PE_StoreU8(B53D_INIT_BYTE, 1u);
        PE_StoreU32(B53C_PRODUCER, 0u);
        PE_StoreU32(B53C_CONSUMER, 0u);
        if (!B53E_SeedBusyDma()) _exit(2);
        Bootstrap_EnableStrict();
        (void)func_80076C34(0x80076664u, 0x80100000u, 8, 0x80110000u);
        /* B53H: the registration and publication B53G proved must still be
         * exactly this, under strict stubs, with the pump translated. */
        if (PE_LoadU32(B53F_DMA_CB_SLOT2) != B53D_QUEUE_PUMP) _exit(3);
        if (PE_GPU_ReadDICR() != 0x00840000u) _exit(4);
        if (PE_LoadU32(B53C_PRODUCER) != 1u) _exit(5);
        if (PE_LoadU32(B53C_CONSUMER) != 0u) _exit(6);
        if (PE_LoadU32(B53C_RING_BASE) != 0x80076664u) _exit(7);
        _exit(0);
    }
    ASSERT(waitpid(pid, &status, 0) == pid,
           "waitpid failed for B53G strict frontier");
    ASSERT(WIFEXITED(status) && WEXITSTATUS(status) == 0,
           "strict enqueue no longer registers and publishes cleanly");
    PASS();
}

/* ═══════════════════════════════════════════════════════════════════
 * Phase 6E-B53H — func_80076EE4 busy-DMA pump prefix (7 tests)
 *
 * Retail 0x80076EE4..0x80077143.  Only the entry busy-DMA fast path is
 * translated: `*(0x1F8010A8) & 0x01000000` non-zero returns exactly 1 with
 * no I_MASK exchange, no queue access, no GPUSTAT read, no callback or
 * DICR change, and no worker invocation.  Expectations below are derived
 * from the literal retail words and cross-checked by tools/b53h_oracle.py.
 * ════════════════════════════════════════════════════════════════════ */

#define B53H_RING_ENTRY_BYTES 0x60u

static void test_B53H_busy_abi_and_return(void)
{
    TEST("B53H_busy_abi_and_return");

    /* Canonical state: one queued entry, DMA2 still in flight. */
    ResetTestState();
    PE_StoreU32(B53C_PRODUCER, 1u);
    PE_StoreU32(B53C_CONSUMER, 0u);
    ASSERT(B53E_SeedBusyDma(), "cannot seed the canonical pending DMA");
    ASSERT((PE_GPU_ReadDMA2CHCR() & 0x01000000u) != 0u,
           "seeded CHCR does not have the retail busy bit set");
    ASSERT(func_80076EE4() == 1, "busy pump did not return retail 1");

    /* The retail authority behind the busy test is named, not duplicated. */
    ASSERT(PE_Pump_Dma2ChcrPointerAddress() == 0x80095860u &&
           PE_Pump_Dma2ChcrMmioAddress() == 0x1F8010A8u,
           "DMA2 CHCR authority addresses differ from retail");

    /* Busy is decided by bit 24 alone, independent of the queue: an empty
     * ring with a busy channel still returns 1. */
    ResetTestState();
    PE_StoreU32(B53C_PRODUCER, 0u);
    PE_StoreU32(B53C_CONSUMER, 0u);
    ASSERT(B53E_SeedBusyDma(), "cannot seed DMA for the empty-queue case");
    ASSERT(func_80076EE4() == 1,
           "busy fast path depends on queue state");
    ASSERT(g_stub_count == 0,
           "busy fast path invoked a boundary");
    PASS();
}

static void test_B53H_busy_test_is_bit24(void)
{
    TEST("B53H_busy_test_is_bit24");
    ResetTestState();
    PE_StoreU32(B53C_PRODUCER, 0u);
    PE_StoreU32(B53C_CONSUMER, 0u);
    ASSERT(B53E_SeedBusyDma(), "cannot seed pending DMA");
    ASSERT(PE_GPU_ReadDMA2CHCR() == 0x01000201u,
           "seeded CHCR is not the retail load value");
    ASSERT(func_80076EE4() == 1, "busy channel did not return 1");

    /* NOT the canonical path: this test explicitly services completion to
     * prove the discriminator is CHCR bit 24 and not "CHCR != 0".  After
     * completion CHCR is 0x00000201, still non-zero, yet the now-complete
     * idle path observes the empty ring and returns zero. */
    ASSERT(PE_GPU_ServiceDMA2Completion(PE_GPU_DMA2EventToken()) == 1,
           "explicit completion was refused");
    ASSERT(PE_GPU_ReadDMA2CHCR() == 0x00000201u &&
           (PE_GPU_ReadDMA2CHCR() & 0x01000000u) == 0u,
           "completion did not clear only the busy bit");
    ASSERT(func_80076EE4() == 0 &&
           PE_IRQ_GetMask() == 0u &&
           CountOrderLog("func_80076EE4_idle_pump") == 0 &&
           PE_Port_GetStopReason() == PE_PORT_STOP_NONE,
           "idle empty-ring path did not return its exact count");
    PASS();
}

static void test_B53H_busy_pump_is_fully_inert(void)
{
    uint8_t *ram_before;
    uint16_t pixel_before[8];
    uint16_t pixel_after[8];
    PeGpuState before;
    PeGpuState after;
    TEST("B53H_busy_pump_is_fully_inert");
    ResetTestState();
    PE_Fill(PE_RAM_BASE, PE_RAM_SIZE, 0x5Au);

    /* Rebuild the exact canonical entry state on top of the poison. */
    PE_StoreU32(B53C_PRODUCER, 1u);
    PE_StoreU32(B53C_CONSUMER, 0u);
    PE_StoreU32(B53C_RING_BASE + 0x00u, 0x80076664u);
    PE_StoreU32(B53C_RING_BASE + 0x04u, B53C_RING_BASE + 0x0Cu);
    PE_StoreU32(B53C_RING_BASE + 0x08u, 0x8012B8B8u);
    PE_StoreU32(B53C_RING_BASE + 0x0Cu, 0x01C80100u);
    PE_StoreU32(B53C_RING_BASE + 0x10u, 0x00010040u);
    PE_StoreU32(B53F_DMA_CB_SLOT2, B53D_QUEUE_PUMP);
    PE_StoreU32(B53D_WORK_MARKER, 1u);
    PE_StoreU32(B53D_DRAWSYNC_CB, 0u);
    (void)PE_IRQ_ExchangeMask(0xBEEFu);
    ASSERT(B53E_SeedBusyDma(), "cannot seed the canonical pending DMA");
    for (uint32_t i = 0; i < 8u; i++) {
        ASSERT(PE_GPU_ReadVRAM(i, 1u, &pixel_before[i]) == 1,
               "VRAM sample failed");
    }
    ram_before = malloc(PE_RAM_SIZE);
    ASSERT(ram_before != NULL, "cannot allocate B53H RAM snapshot");
    memcpy(ram_before, PE_TranslateConst(PE_RAM_BASE, PE_RAM_SIZE),
           PE_RAM_SIZE);
    PE_GPU_GetState(&before);

    ASSERT(func_80076EE4() == 1, "canonical busy pump did not return 1");

    /* Not one guest byte may change — ring, indices, callback slot, work
     * marker, both saved-I_MASK words, and every unrelated byte. */
    ASSERT(memcmp(ram_before,
                  PE_TranslateConst(PE_RAM_BASE, PE_RAM_SIZE),
                  PE_RAM_SIZE) == 0,
           "busy pump mutated guest memory");
    ASSERT(memcmp(PE_TranslateConst(B53C_RING_BASE, B53H_RING_ENTRY_BYTES),
                  ram_before + (B53C_RING_BASE - PE_RAM_BASE),
                  B53H_RING_ENTRY_BYTES) == 0,
           "busy pump mutated the queued entry");

    /* No hardware field may change either. */
    PE_GPU_GetState(&after);
    ASSERT(memcmp(&before, &after, sizeof(before)) == 0,
           "busy pump progressed GPU/DMA/VBlank/parser state");
    ASSERT(PE_IRQ_GetMask() == 0xBEEFu,
           "busy pump touched the single I_MASK authority");
    ASSERT(PE_GPU_ReadStatus() == before.status &&
           PE_GPU_VSyncQuery() == before.vsync_count &&
           PE_GPU_ReadDICR() == before.dicr &&
           PE_GPU_ReadDPCR() == before.dpcr,
           "busy pump changed GPUSTAT, VBlank, DICR, or DPCR");
    for (uint32_t i = 0; i < 8u; i++) {
        ASSERT(PE_GPU_ReadVRAM(i, 1u, &pixel_after[i]) == 1 &&
               pixel_after[i] == pixel_before[i],
               "busy pump mutated VRAM");
    }
    ASSERT(g_stub_count == 0 && g_bootstrap_arg4_call_count == 0 &&
           PE_Port_GetStopReason() == PE_PORT_STOP_NONE,
           "busy pump invoked a worker, callback, or boundary");
    free(ram_before);
    PASS();
}

static void test_B53H_busy_pump_never_completes_dma(void)
{
    TEST("B53H_busy_pump_never_completes_dma");
    ResetTestState();
    PE_StoreU32(B53C_PRODUCER, 1u);
    PE_StoreU32(B53C_CONSUMER, 0u);
    PE_StoreU32(B53C_RING_BASE, 0x80076664u);
    ASSERT(B53E_SeedBusyDma(), "cannot seed the canonical pending DMA");

    /* Repeated pumping never makes progress: the transfer stays in flight,
     * completion never becomes pending, and no interrupt is asserted. */
    for (int i = 0; i < 8; i++) {
        ASSERT(func_80076EE4() == 1,
               "repeated busy pump is not deterministic");
        ASSERT(PE_GPU_DMA2Pending() == 1 &&
               PE_GPU_DMA2CompletionPending() == 0 &&
               PE_GPU_DMA2InterruptAsserted() == 0,
               "repeated busy pump advanced the transfer");
        ASSERT(PE_LoadU32(B53C_PRODUCER) == 1u &&
               PE_LoadU32(B53C_CONSUMER) == 0u &&
               PE_LoadU32(B53C_RING_BASE) == 0x80076664u,
               "repeated busy pump consumed the queue");
    }
    ASSERT(CountOrderLog("func_80076664") == 0 && g_stub_count == 0,
           "busy pump invoked the queued worker");
    ASSERT(PE_GPU_VSyncQuery() == 0u,
           "busy pump advanced VBlank");
    PASS();
}

static void test_B53H_dispatcher_busy_integration(void)
{
    PeGpuState before;
    PeGpuState after;
    TEST("B53H_dispatcher_busy_integration");
    ResetTestState();
    PE_StoreU8(B53D_INIT_BYTE, 1u);
    PE_StoreU32(B53E_RECT, 0x11112222u);
    PE_StoreU32(B53E_RECT + 4u, 0x33334444u);
    (void)PE_IRQ_ExchangeMask(0xBEEFu);
    ASSERT(B53E_SeedBusyDma(), "cannot seed the canonical pending DMA");
    PE_GPU_GetState(&before);

    /* Registration + publication + a real busy-DMA pump return: the
     * dispatcher now completes and yields the retail pending count. */
    ASSERT(func_80076C34(0x80076664u, B53E_RECT, 8, 0x80110000u) == 1,
           "dispatcher did not return the retail pending count");
    PE_GPU_GetState(&after);

    ASSERT(PE_LoadU32(B53C_PRODUCER) == 1u &&
           PE_LoadU32(B53C_CONSUMER) == 0u,
           "publication moved the consumer or mispublished the producer");
    ASSERT(PE_LoadU32(B53C_RING_BASE) == 0x80076664u &&
           PE_LoadU32(B53C_RING_BASE + 4u) == B53C_RING_BASE + 0x0Cu &&
           PE_LoadU32(B53C_RING_BASE + 8u) == 0x80110000u &&
           PE_LoadU32(B53C_RING_BASE + 0x0Cu) == 0x11112222u &&
           PE_LoadU32(B53C_RING_BASE + 0x10u) == 0x33334444u,
           "published entry differs from retail");
    ASSERT(PE_LoadU32(B53F_DMA_CB_SLOT2) == B53D_QUEUE_PUMP &&
           after.dicr == 0x00840000u,
           "B53G registration state regressed");
    ASSERT(PE_IRQ_GetMask() == 0xBEEFu &&
           PE_LoadU32(B53D_SAVED_IMASK) == 0xBEEFu,
           "dispatcher lost the I_MASK save/restore around publication");
    ASSERT(PE_GPU_DMA2Pending() == 1 &&
           PE_GPU_DMA2CompletionPending() == 0,
           "dispatcher completed the in-flight transfer");
    ASSERT(CountOrderLog("func_80076664") == 0 &&
           CountOrderLog("func_80076EE4_idle_pump") == 0 &&
           g_stub_count == 0 &&
           PE_Port_GetStopReason() == PE_PORT_STOP_NONE,
           "dispatcher invoked a worker or fabricated a boundary");
    before.dicr = after.dicr;
    ASSERT(memcmp(&before, &after, sizeof(before)) == 0,
           "dispatcher progressed hardware beyond the DICR RMW");
    PASS();
}

static void test_B53H_boundary_is_not_masked_by_frame_limit(void)
{
    unsigned epoch;
    TEST("B53H_boundary_is_not_masked_by_frame_limit");
    ResetTestState();
    PE_StoreU8(B53D_INIT_BYTE, 1u);
    PE_StoreU32(B53C_PRODUCER, 4u);
    PE_StoreU32(B53C_CONSUMER, 1u);
    PE_StoreU32(B53D_DRAWSYNC_CB, 0x80012345u);

    /* Latch a DIFFERENT stop reason first.  PE_Port_RequestStop keeps the
     * FIRST reason, so a pump boundary must be reported through its own
     * explicit signal rather than inferred from the stop reason. */
    PE_Port_RequestStop(PE_PORT_STOP_FRAME_LIMIT);
    ASSERT(PE_Port_GetStopReason() == PE_PORT_STOP_FRAME_LIMIT,
           "frame-limit stop reason was not latched first");

    epoch = PE_Port_StopEpoch();

    /* DMA2 is idle, so the dispatcher's opportunistic pump reaches the
     * zero worker already present at consumer slot 1.  Retail unconditionally
     * executes jalr; zero is therefore an honest indirect boundary, not an
     * empty callback.  The older frame-limit reason must not hide its new
     * stop epoch. */
    ASSERT(func_80076C34(0x80076664u, 0x80100000u, 8, 0x80110000u) == 0,
           "masked pump boundary produced a fabricated pending count");
    ASSERT(CountOrderLog("func_00000000") == 1 &&
           PE_Port_StopEpoch() == epoch + 1u &&
           PE_Port_GetStopReason() == PE_PORT_STOP_FRAME_LIMIT &&
           PE_IRQ_GetMask() == 0u,
           "typed worker boundary was hidden under a latched stop reason");
    PASS();
}

static void test_B53H_strict_advances_past_dispatcher(void)
{
    pid_t pid;
    int status = 0;
    TEST("B53H_strict_advances_past_dispatcher");
    ResetTestState();
    pid = fork();
    ASSERT(pid >= 0, "fork failed for B53H strict advance");
    if (pid == 0) {
        Bootstrap_Init();
        B52_SeedGpuDispatch();
        PE_StoreU8(B53D_INIT_BYTE, 1u);
        if (!B53E_SeedBusyDma()) _exit(2);
        Bootstrap_EnableStrict();
        /* Under strict stubs the whole enqueue + busy pump must complete
         * without invoking any provider, leaving the transfer in flight
         * and the queued request unconsumed for a later real completion. */
        if (func_80076C34(0x80076664u, 0x80100000u, 8, 0x80110000u) != 1)
            _exit(3);
        if (!PE_GPU_DMA2Pending()) _exit(4);
        if (PE_GPU_DMA2CompletionPending()) _exit(5);
        if (PE_LoadU32(B53C_CONSUMER) != 0u) _exit(6);
        if (PE_LoadU32(B53C_PRODUCER) != 1u) _exit(7);
        _exit(0);
    }
    ASSERT(waitpid(pid, &status, 0) == pid,
           "waitpid failed for B53H strict advance");
    ASSERT(WIFEXITED(status) && WEXITSTATUS(status) == 0,
           "strict busy-DMA dispatch no longer completes cleanly");
    PASS();
}

static void test_B53H_stop_epoch_distinguishes_latched_stops(void)
{
    unsigned epoch;
    TEST("B53H_stop_epoch_distinguishes_latched_stops");
    ResetTestState();

    /* The epoch primitive.  PE_Port_RequestStop keeps the FIRST reason, so
     * the reason alone cannot tell a caller that a *further* stop was just
     * requested.  The epoch is monotonic and must count every request. */
    ASSERT(PE_Port_StopEpoch() == 0u, "run-control reset left a stop epoch");
    PE_Port_RequestStop(PE_PORT_STOP_FRAME_LIMIT);
    ASSERT(PE_Port_StopEpoch() == 1u, "first stop did not advance the epoch");
    epoch = PE_Port_StopEpoch();
    PE_Port_RequestStop(PE_PORT_STOP_UNRESOLVED_BOUNDARY);
    ASSERT(PE_Port_GetStopReason() == PE_PORT_STOP_FRAME_LIMIT,
           "stop reason stopped being sticky-first");
    ASSERT(PE_Port_StopEpoch() == epoch + 1u,
           "a second stop was invisible to the epoch as well as the reason");

    /* Integration: an EARLIER unrelated stop must not be mistaken for a
     * nested worker boundary on the direct-issue path.  Retail
     * 0x80076D40..0x80076D4C restores the saved I_MASK unconditionally when
     * the worker returns, so suppressing that restore would fabricate a
     * retail control-flow cut that never happened. */
    ResetTestState();
    B53E_SetupRetailGpu();
    PE_StoreU8(B53D_INIT_BYTE, 1u);
    B53E_StoreRect(9, 11, 1, 1);
    PE_StoreU32(B53E_SOURCE, 0x7777AAAAu);
    (void)PE_IRQ_ExchangeMask(0xBEEFu);
    /* Same reason a real worker boundary would use — precisely the case the
     * old stop-reason comparison could not distinguish. */
    PE_Port_RequestStop(PE_PORT_STOP_UNRESOLVED_BOUNDARY);
    epoch = PE_Port_StopEpoch();
    ASSERT(epoch > 0u, "pre-latched stop was not recorded");
    ASSERT(func_80076C34(0x80076664u, B53E_RECT, 8, B53E_SOURCE) == 0,
           "direct issue under a latched stop did not return retail zero");
    ASSERT(B53B_Pixel(9, 11) == 0xAAAAu,
           "direct worker did not run under a latched stop");
    ASSERT(PE_Port_StopEpoch() == epoch,
           "direct issue latched a stop it should not have");
    ASSERT(PE_IRQ_GetMask() == 0xBEEFu &&
           PE_LoadU32(B53D_SAVED_IMASK) == 0xBEEFu,
           "a pre-latched stop suppressed the mandatory I_MASK restore");
    PASS();
}

/* ═══════════════════════════════════════════════════════════════════
 * Phase 6E-B53I-B2 — DMA2 completion edge and retail IRQ delivery
 *
 * The focused fixtures preserve completion, DICR edge bridging, and CPU
 * service as three explicit phases.  B53I-C now lets the canonical callback
 * return through the complete idle consumer; the B2 acknowledgement and
 * one-token contracts remain independently asserted here.
 * ════════════════════════════════════════════════════════════════════ */

static int B53I_B2_SeedCanonicalChain(uint8_t *entry_snapshot)
{
    func_80073C94();
    (void)func_80074A44(0);
    PE_StoreU8(B53D_INIT_BYTE, 1u);

    /* Exact first canonical LoadImage: RECT {704,64,32,64}, 2048 pixels,
     * 1024 DMA words, and no CPU remainder. */
    for (uint32_t i = 0u; i < 1024u; i++) {
        PE_StoreU32(0x8012A8B8u + i * 4u,
                    (0x2000u + i * 2u) |
                    ((0x2001u + i * 2u) << 16));
    }
    B53E_StoreRect(704, 64, 32, 64);
    if (func_80076C34(0x80076664u, B53E_RECT, 8,
                      0x8012A8B8u) != 0) return 0;
    if (PE_GPU_ReadDMA2MADR() != 0x8012A8B8u ||
        PE_GPU_ReadDMA2BCR() != 0x00400010u ||
        PE_GPU_ReadDMA2CHCR() != 0x01000201u) return 0;

    /* Exact queued second LoadImage: RECT {256,456,64,1}, 32 DMA words. */
    for (uint32_t i = 0u; i < 32u; i++) {
        PE_StoreU32(0x8012B8B8u + i * 4u,
                    (0x6000u + i * 2u) |
                    ((0x6001u + i * 2u) << 16));
    }
    B53E_StoreRect(256, 456, 64, 1);
    if (func_80076C34(0x80076664u, B53E_RECT, 8,
                      0x8012B8B8u) != 1) return 0;
    if (PE_LoadU32(B53C_PRODUCER) != 1u ||
        PE_LoadU32(B53C_CONSUMER) != 0u ||
        PE_LoadU32(B53F_DMA_CB_SLOT2) != 0x80076EE4u ||
        PE_GPU_ReadStoredDICR() != 0x00840000u) return 0;
    if (entry_snapshot != NULL) {
        memcpy(entry_snapshot,
               PE_TranslateConst(B53C_RING_BASE, B53H_RING_ENTRY_BYTES),
               B53H_RING_ENTRY_BYTES);
    }
    return 1;
}

static void test_B53I_B2_dicr_physical_edges(void)
{
    TEST("B53I_B2_dicr_physical_edges");
    ResetTestState();

    PE_GPU_WriteDICR(0x00840000u);
    ASSERT(PE_GPU_ReadStoredDICR() == 0x00840000u &&
           PE_GPU_ReadDICR() == 0x00840000u &&
           !PE_GPU_DICRRisingEdgePending(),
           "enable-only DICR state raised physical bit 31");
    ASSERT(PE_GPU_LatchDMACompletionFlag(2u) &&
           PE_GPU_ReadStoredDICR() == 0x04840000u &&
           PE_GPU_ReadDICR() == 0x84840000u &&
           PE_GPU_DICRRisingEdgePending(),
           "enabled completion did not create stored flag/derived edge");
    ASSERT(PE_GPU_TakeDICRRisingEdge() == 1 &&
           PE_GPU_TakeDICRRisingEdge() == 0,
           "DICR edge was not a one-shot latch");

    /* Retain the flag while master is low, then re-enable master. */
    PE_GPU_WriteDICR(0x00040000u);
    ASSERT(PE_GPU_ReadStoredDICR() == 0x04040000u &&
           PE_GPU_ReadDICR() == 0x04040000u,
           "master-off control write lost a retained flag");
    PE_GPU_WriteDICR(0x00840000u);
    ASSERT(PE_GPU_ReadDICR() == 0x84840000u &&
           PE_GPU_TakeDICRRisingEdge() == 1,
           "master 0->1 with retained flag did not raise an edge");
    PE_GPU_WriteDICR(0x00800000u);
    ASSERT(PE_GPU_ReadDICR() == 0x84800000u &&
           !PE_GPU_DICRRisingEdgePending(),
           "channel-disable incorrectly lowered/retriggered retained flag");
    PE_GPU_WriteDICR(0x04800000u);
    ASSERT(PE_GPU_ReadStoredDICR() == 0x00800000u &&
           PE_GPU_ReadDICR() == 0x00800000u &&
           !PE_GPU_DICRRisingEdgePending(),
           "W1C acknowledgement created a rising edge");

    PE_GPU_WriteDICR(0u);
    PE_GPU_WriteDICR(PE_GPU_DICR_FORCE);
    ASSERT(PE_GPU_ReadStoredDICR() == PE_GPU_DICR_FORCE &&
           PE_GPU_ReadDICR() ==
               (PE_GPU_DICR_MASTER_FLAG | PE_GPU_DICR_FORCE) &&
           PE_GPU_TakeDICRRisingEdge() == 1,
           "force bit did not derive bit31/rising edge");
    PE_GPU_WriteDICR(PE_GPU_DICR_FORCE);
    ASSERT(!PE_GPU_DICRRisingEdgePending(),
           "unchanged-high force bit retriggered");
    PE_GPU_WriteDICR(0u);
    PE_GPU_WriteDICR(PE_GPU_DICR_FORCE);
    ASSERT(PE_GPU_TakeDICRRisingEdge() == 1,
           "force low->high did not retrigger after a fall");
    PE_GPU_WriteDICR(PE_GPU_DICR_MASTER_FLAG);
    ASSERT((PE_GPU_ReadStoredDICR() & PE_GPU_DICR_MASTER_FLAG) == 0u &&
           PE_GPU_ReadDICR() == 0u,
           "read-only physical bit31 was stored by software");
    PASS();
}

static void test_B53I_B2_sticky_edge_bridge_and_reset(void)
{
    PeIrqGeneration generation;
    TEST("B53I_B2_sticky_edge_bridge_and_reset");
    ResetTestState();
    func_80073C94();
    generation = PE_IRQ_Generation();

    PE_GPU_WriteDICR(0x00840000u);
    ASSERT(PE_GPU_LatchDMACompletionFlag(2u), "cannot latch completion");
    PE_GPU_WriteDICR(0x04840000u); /* fall before the bridge */
    ASSERT(PE_GPU_ReadDICR() == 0x00840000u &&
           PE_GPU_DICRRisingEdgePending() &&
           PE_IRQ_ReadStatus() == 0u,
           "fall erased edge or DICR wrote I_STAT directly");
    ASSERT(PE_IRQ_BridgeDICRRisingEdge(generation) ==
               PE_IRQ_EDGE_ASSERTED &&
           PE_IRQ_ReadStatus() == 0x0008u &&
           !PE_GPU_DICRRisingEdgePending(),
           "sticky edge did not bridge exactly once");
    PE_IRQ_WriteStatus(0xFFF7u);
    ASSERT(PE_IRQ_BridgeDICRRisingEdge(generation) == PE_IRQ_EDGE_NONE &&
           PE_IRQ_ReadStatus() == 0u,
           "low DICR level retriggered source 3");

    /* Exact high-level sequence: acknowledge I_STAT while DICR remains
     * asserted. The bridge consumes edges, not levels, so it must not
     * reassert until DICR first falls and rises again. */
    PE_GPU_WriteDICR(0x00840000u);
    ASSERT(PE_GPU_LatchDMACompletionFlag(2u) &&
           PE_IRQ_BridgeDICRRisingEdge(generation) ==
               PE_IRQ_EDGE_ASSERTED &&
           PE_GPU_ReadDICR() == 0x84840000u,
           "cannot seed bridged high-DICR state");
    PE_IRQ_WriteStatus(0xFFF7u);
    ASSERT(PE_GPU_ReadDICR() == 0x84840000u &&
           PE_IRQ_BridgeDICRRisingEdge(generation) == PE_IRQ_EDGE_NONE &&
           PE_IRQ_ReadStatus() == 0u,
           "high DICR level retriggered after I_STAT acknowledgement");
    PE_GPU_WriteDICR(0x04840000u);

    PE_GPU_WriteDICR(PE_GPU_DICR_FORCE);
    ASSERT(PE_GPU_DICRRisingEdgePending(), "force edge not pending");
    PE_Sdk_ResetState();
    PE_GPU_WriteDICR(PE_GPU_DICR_FORCE); /* fresh post-reset edge */
    ASSERT(PE_IRQ_BridgeDICRRisingEdge(generation) == PE_IRQ_EDGE_STALE &&
           PE_IRQ_ReadStatus() == 0u &&
           PE_GPU_DICRRisingEdgePending(),
           "stale generation consumed a fresh post-reset DICR edge");
    ASSERT(PE_IRQ_BridgeDICRRisingEdge(PE_IRQ_Generation()) ==
               PE_IRQ_EDGE_ASSERTED &&
           PE_IRQ_ReadStatus() == 0x0008u &&
           !PE_GPU_DICRRisingEdgePending(),
           "current generation could not consume fresh post-reset edge");
    PASS();
}

static void test_B53I_B2_completion_data_and_gating(void)
{
    uint64_t token;
    TEST("B53I_B2_completion_data_and_gating");

    ResetTestState();
    PE_StoreU32(0x80180000u, 0x56781234u);
    ASSERT(B53E_SeedBusyDma(), "enabled completion seed failed");
    PE_GPU_SetDMA2InterruptEnabled(1);
    token = PE_GPU_DMA2EventToken();
    ASSERT(PE_GPU_ServiceDMA2Completion(token) &&
           B53B_Pixel(0u, 0u) == 0x1234u &&
           PE_GPU_ReadDMA2CHCR() == 0x00000201u &&
           PE_GPU_ReadStoredDICR() == 0x04840000u &&
           PE_GPU_ReadDICR() == 0x84840000u &&
           PE_IRQ_ReadStatus() == 0u,
           "valid completion did not expose data/CHCR/DICR-only phase");

    ResetTestState();
    PE_StoreU32(0x80180000u, 0xDEF09ABCu);
    ASSERT(B53E_SeedBusyDma(), "disabled completion seed failed");
    PE_GPU_WriteDICR(0x00800000u); /* master on, channel 2 disabled */
    token = PE_GPU_DMA2EventToken();
    ASSERT(PE_GPU_ServiceDMA2Completion(token) &&
           B53B_Pixel(0u, 0u) == 0x9ABCu &&
           PE_GPU_ReadDMA2CHCR() == 0x00000201u &&
           PE_GPU_ReadStoredDICR() == 0x00800000u &&
           !PE_GPU_DICRRisingEdgePending(),
           "channel-disabled completion created an interrupt flag");

    ResetTestState();
    PE_StoreU32(0x80180000u, 0x24681357u);
    ASSERT(B53E_SeedBusyDma(), "master-off completion seed failed");
    PE_GPU_WriteDICR(0x00040000u); /* channel 2 enabled, master disabled */
    token = PE_GPU_DMA2EventToken();
    ASSERT(PE_GPU_ServiceDMA2Completion(token) &&
           B53B_Pixel(0u, 0u) == 0x1357u &&
           PE_GPU_ReadStoredDICR() == 0x00040000u &&
           !PE_GPU_DICRRisingEdgePending(),
           "master-disabled completion created an interrupt flag");
    PASS();
}

static void test_B53I_B2_focused_idle_boundary_chain(void)
{
    uint8_t before[B53H_RING_ENTRY_BYTES];
    PeIrqDeliveryTrace trace;
    PeIrqGeneration generation;
    uint64_t token;
    TEST("B53I_B2_focused_idle_boundary_chain");
    ResetTestState();
    ASSERT(B53I_B2_SeedCanonicalChain(before),
           "cannot seed canonical B2 chain");
    token = PE_GPU_DMA2EventToken();
    generation = PE_IRQ_Generation();
    /* Seeding authentically calls the busy pump once.  Start a focused
     * actual-entry observation window so an illicit early call cannot hide
     * in that pump's otherwise silent busy fast path. */
    PE_Pump_TraceReset();
    ASSERT(PE_Pump_EntryCount() == 0u,
           "pump entry evidence did not reset");

    ASSERT(PE_GPU_ServiceDMA2Completion(token) &&
           !PE_GPU_DMA2Pending() &&
           PE_GPU_ReadDMA2CHCR() == 0x00000201u &&
           PE_GPU_ReadStoredDICR() == 0x04840000u &&
           PE_GPU_ReadDICR() == 0x84840000u &&
           PE_IRQ_ReadStatus() == 0u &&
           B53B_Pixel(704u, 64u) == 0x2000u,
           "hardware completion phase is not separately observable");
    ASSERT(PE_Pump_EntryCount() == 0u &&
           CountOrderLog("func_80076EE4_idle_pump") == 0,
           "hardware completion executed a callback");

    ASSERT(PE_IRQ_BridgeDICRRisingEdge(generation) ==
               PE_IRQ_EDGE_ASSERTED &&
           PE_IRQ_ReadStatus() == 0x0008u &&
           PE_GPU_ReadDICR() == 0x84840000u &&
           PE_Pump_EntryCount() == 0u,
           "source-3 edge phase is not separately observable");
    PE_IRQ_AssertSources(0x0020u); /* unrelated, masked pending source */
    ASSERT(PE_IRQ_ServicePendingForGeneration(generation) ==
               PE_IRQ_SERVICE_RETURNED,
           "canonical source3/DMA callback did not return normally");
    ASSERT(PE_Pump_EntryCount() == 1u,
           "CPU/DMA service did not enter the pump exactly once");

    PE_IRQ_GetDeliveryTrace(&trace);
    ASSERT(trace.edge_assert_order < trace.cpu_ack_order &&
           trace.cpu_ack_order < trace.cpu_callback_order &&
           trace.cpu_callback_order < trace.dma_ack_order &&
           trace.dma_ack_order < trace.dma_callback_order,
           "CPU/DMA acknowledgement order differs from retail");
    ASSERT(trace.cpu_service_entries == 1u &&
           trace.dma_dispatch_entries == 1u &&
           trace.cpu_ack_count == 1u && trace.cpu_ack_sources[0] == 3u &&
           trace.dma_ack_count == 1u && trace.dma_ack_channels[0] == 2u &&
           trace.last_cpu_ack_write == 0xFFF7u &&
           trace.last_dma_ack_write == 0x04840000u &&
           trace.last_cpu_handler == 0x80074520u &&
           trace.last_dma_handler == 0x80076EE4u,
           "callback identities or dispatch scan evidence is wrong");
    ASSERT(trace.dma_callback_chcr == 0x00000201u &&
           trace.dma_callback_dicr == 0x00840000u &&
           (trace.dma_callback_istat & 0x0008u) == 0u &&
           (trace.dma_callback_istat & 0x0020u) != 0u,
           "DMA callback did not observe idle/acknowledged hardware state");
    ASSERT(PE_IRQ_ReadStatus() == 0x0020u &&
           PE_GPU_ReadStoredDICR() == 0x00800000u &&
           PE_GPU_ReadDICR() == 0x00800000u &&
           PE_LoadU16(B53I_IRQ_DISPATCH_ACTIVE) == 0u,
           "normal callback return lost acknowledgements or active cleanup");
    ASSERT(PE_LoadU32(B53C_PRODUCER) == 1u &&
           PE_LoadU32(B53C_CONSUMER) == 1u &&
           memcmp(before,
                  PE_TranslateConst(B53C_RING_BASE,
                                    B53H_RING_ENTRY_BYTES),
                  B53H_RING_ENTRY_BYTES) == 0,
           "idle callback did not consume exactly one byte-stable entry");
    ASSERT(PE_GPU_DMA2Pending() &&
           PE_GPU_ReadDMA2CHCR() == 0x01000201u &&
           PE_GPU_ReadDMA2MADR() == 0x8012B8B8u &&
           PE_GPU_ReadDMA2BCR() == 0x00020010u &&
           CountOrderLog("func_80076EE4_idle_pump") == 0 &&
           CountOrderLog("func_80076664") == 0 &&
           PE_Port_GetStopReason() == PE_PORT_STOP_NONE,
           "idle consumer failed to issue exactly the later DMA");
    PASS();
}

